#!/bin/bash
# Build/refresh the corpus under $1 (default ~/.cache/pijul-git-speed/corpus):
#   synthetic/  generated by make_synthetic.sh (merges, renames, binaries, two roots)
#   ryvfs/ usagui/  fresh clones of BlankMauser/ryvfs and BlankMauser/usagui
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
C=${1:-$HOME/.cache/pijul-git-speed/corpus}; mkdir -p "$C"
rm -rf "$C/synthetic"; "$HERE/make_synthetic.sh" "$C/synthetic"
for r in ryvfs usagui; do
  rm -rf "$C/$r"
  git clone --quiet --single-branch --no-tags "https://github.com/BlankMauser/$r" "$C/$r"
  echo "$r: $(git -C "$C/$r" rev-parse HEAD) $(git -C "$C/$r" rev-list --count HEAD) commits, $(git -C "$C/$r" rev-list --merges --count HEAD) merges"
done
